'use strict';
(async()=>{
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const [r,expectations]=await Promise.all(['phase-quality.json','expectations.json'].map(p=>fetch(p).then(x=>{if(!x.ok)throw Error(p);return x.json()})));
const c=r.counts,nodes=new Map(r.nodes.map(n=>[n.id,n])),issues=r.issues||[],errors=issues.filter(i=>i.severity==='error'),reviews=issues.filter(i=>i.severity==='review'),isolated=r.nodes.filter(n=>n.neighbors===0),chapterSet=new Set(r.scope.chapters);
const ref=id=>id.replace('GEN.','Gen ').replace('.',':');const nodeLink=n=>`<a class="node-link" href="index.html?entity=${encodeURIComponent(n.id)}">${esc(n.label||n.id)}</a>`;
const active=expectations.entities.filter(e=>e.evidence.every(v=>chapterSet.has(Number(v.split('.')[1]))));
const majorRows=active.map(e=>{const n=nodes.get(e.id),findings=issues.filter(i=>i.code.startsWith('major_')&&(i.context?.expected?.id===e.id||i.context?.entity===e.id));return `<tr><td>${n?nodeLink(n):esc(e.id)}</td><td>${!n?'Missing':findings.length?'Review finding':'Checks passed'}</td><td>${n?.neighbors??'—'}</td><td>${e.evidence.map(ref).map(esc).join(', ')}</td></tr>`}).join('');
const gap=r.gap_resolution;let gapSection='';
if(gap?.ledger_sha256){
 const response=await fetch('gap-resolution-ledger.json');if(!response.ok)throw Error('gap ledger');const ledger=await response.json();
 const label=id=>nodes.get(id)?.label||id;
 const passageLink=(id,entity)=>`<a class="verse-button" href="index.html?entity=${encodeURIComponent(entity)}&verse=${encodeURIComponent(id)}">${esc(ref(id))}</a>`;
 const entries=ledger.items.map(item=>{
  const subjectNames=(item.entities||[]).map(label).join(' · '),original=item.original_issue;
  const supporting=(item.supporting_relations||[]).map(s=>{const e=s.expected_record;return `<article class="relation"><div>${nodeLink({id:e.subject,label:label(e.subject)})} <span>${esc(e.predicate.replaceAll('_',' '))} → </span>${nodeLink({id:e.object,label:label(e.object)})}</div><p class="caption">IN-TEXT ASSERTION · ${esc(e.assertion.mode)}${e.assertion.speaker?' · Speaker: '+esc(label(e.assertion.speaker)):''}</p>${e.note?`<p>${esc(e.note)}</p>`:''}<div class="chips">${e.evidence.map(v=>passageLink(v,e.subject)).join('')}</div></article>`}).join('');
  return `<details class="gap-entry"><summary><span class="gap-state">${esc(item.status)}</span> ${esc(original.code.replaceAll('_',' '))} · ${esc(subjectNames)}</summary><p>${esc(original.message)}</p><p><strong>Source-based resolution:</strong> ${esc(item.reason)}</p>${supporting}<p class="caption">Review: ${esc(item.review?.status)} · ${esc(item.review?.reviewer)}</p></details>`;
 }).join('');
 gapSection=`<section class="quality-section" id="gap-resolutions"><h3>What changed since the previous phase?</h3><p><strong>${gap.resolved} of ${gap.total} prior coverage gaps resolved</strong> through source-backed relationship additions. ${gap.partial} partial · ${gap.residual} residual · ${gap.unreviewed} awaiting review.</p><p>This ledger follows the original gaps individually, rather than treating fewer isolated nodes or removed warnings as proof. Resolving this checklist does not imply exhaustive Genesis coverage.</p><details><summary>Explore all ${gap.total} original gaps, new connections and passages</summary>${entries}</details><p><a class="node-link" href="gap-resolution.md">Full gap-resolution report</a> · <a class="node-link" href="gap-resolution-ledger.json">Machine-readable ledger</a></p></section>`;
}
const omissions=reviews.filter(i=>i.disposition?.decision==='accepted_omission').length;
const finding=i=>`<li><strong>${esc(i.code.replaceAll('_',' '))}</strong><p>${esc(i.message)}</p>${i.context?.label?`<p>${nodeLink(i.context)}</p>`:''}${i.disposition?`<p><strong>Reviewed:</strong> ${esc(i.disposition.decision?.replaceAll('_',' '))}. ${esc(i.disposition.reason)} <span class="caption">Reviewer: ${esc(i.disposition.reviewer)}</span></p>`:'<p><strong>Unresolved — blocks release.</strong></p>'}<details><summary>Evidence & context</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:11px">${esc(JSON.stringify(i.context,null,2))}</pre></details></li>`;
document.getElementById('qualityContent').innerHTML=`<span class="quality-status ${r.status==='PASS'?'':'fail'}">${r.status==='PASS'?'Release gate passed':esc(r.status.replaceAll('_',' '))}</span><p class="caption">Dataset ${esc(r.dataset_version)} · Genesis ${Math.min(...r.scope.chapters)}–${Math.max(...r.scope.chapters)} · Selected annotations, not exhaustive extraction</p><div class="quality-stats">${[['entities','Selected entities'],['relations','Curated relationships'],['mentions','Explicit mentions'],['verses','Source verses']].map(([k,l])=>`<div class="quality-stat"><strong>${Number(c[k]).toLocaleString()}</strong><span>${l}</span></div>`).join('')}</div><section class="quality-section"><h3>Hard failures vs. review findings</h3><p><strong>${c.errors} hard failures</strong> · <strong>${c.unresolved_review} unresolved review findings</strong> · ${c.review_items} review findings retained for transparency.</p><p><strong>${omissions} accepted coverage omissions</strong> remain visible; ${reviews.filter(i=>i.disposition).length-omissions} other findings were accepted after source review. Accepted does not mean complete.</p><p>Broken source references and integrity errors stop publication. Missing checklist entries, disconnected nodes and changes from the previous phase require review. An intentional omission can be documented; a hard error cannot be waived.</p>${errors.length?`<ul>${errors.map(finding).join('')}</ul>`:'<p class="caption">No hard failures in this released dataset.</p>'}<details><summary>Read ${reviews.length} review findings and decisions</summary><ul>${reviews.map(finding).join('')}</ul></details></section>${gapSection}<section class="quality-section"><h3>Major-character checklist</h3><p>${active.length} source-anchored character entries checked in the current chapter scope. This is a deliberately selected checklist, not a claim that every important character or relationship has been captured.</p><div class="table-scroll"><table><thead><tr><th>Character</th><th>Check result</th><th>Neighbors</th><th>Source anchors</th></tr></thead><tbody>${majorRows}</tbody></table></div><p class="caption">${esc(r.expectations.method)}</p></section><section class="quality-section"><h3>Unconnected nodes & groups</h3><p><strong>${c.isolated} isolated nodes</strong> · ${c.components} connected group${c.components===1?'':'s'}. Isolation means no curated relationship connects that entity; it does not mean the entity is wrong or absent from the text. Shared passages are not turned into invented edges.</p><details><summary>See all ${isolated.length} isolated nodes</summary><div class="table-scroll"><table><thead><tr><th>Entity</th><th>Type</th><th>Mentions</th><th>Description evidence</th></tr></thead><tbody>${isolated.map(n=>`<tr><td>${nodeLink(n)}</td><td>${esc(n.type.replaceAll('_',' '))}</td><td>${n.mentions}</td><td>${n.evidence.map(ref).map(esc).join(', ')}</td></tr>`).join('')}</tbody></table></div></details></section><section class="quality-section"><h3>Reproducibility & limits</h3><p>Regression comparison: <strong>${esc(r.regression?.status?.replaceAll('_',' ')||'not run')}</strong>. The release command rebuilds the dataset, runs tests and checks the gate before copying these published files.</p><ul>${r.limitations.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p class="caption">Published graph SHA256<br><code>${esc(r.dataset_sha256)}</code></p><p><a class="node-link" href="phase-quality.json">Machine-readable report</a> · <a class="node-link" href="phase-quality.md">Full report text</a> · <a class="node-link" href="provenance.json">Source provenance</a> · <a class="node-link" href="licensing.md">Licenses &amp; attribution</a></p></section>`;
})().catch(e=>{document.getElementById('qualityContent').textContent='The quality report could not load. Return to the graph or refresh to try again.';console.error(e)});
